<?php

declare(strict_types=1);
namespace StageArtCore\Presentation\Admin;
use StageArtCore\Presentation\PublicSite\SiteStructure;
use StageArtCore\Domain\Member\MemberRepository;

final class SiteStructureAdmin
{
    public function __construct(){add_action('admin_post_stageart_save_homepage',[$this,'saveHomepage']);add_action('admin_post_stageart_save_menu',[$this,'saveMenu']);}
    public function register():void{add_submenu_page('stageart-plugin','トップページ設定','トップページ設定','manage_options','stageart-homepage',[$this,'renderHomepage']);add_submenu_page('stageart-plugin','メニュー構成','メニュー構成','manage_options','stageart-menu',[$this,'renderMenu']);}
    private function data():array{return[get_posts(['post_type'=>'stageart_production','post_status'=>['publish','draft'],'numberposts'=>-1,'orderby'=>'title','order'=>'ASC']),(new MemberRepository())->all(false)];}
    private function picker(array$p,array$m,string$selected):string{$h='<option value="">選択してください</option><optgroup label="システムページ">';foreach(SiteStructure::systemLabels()as$k=>$v)$h.='<option value="system:'.esc_attr($k).'"'.selected($selected,'system:'.$k,false).'>'.esc_html($v).'</option>'; $h.='</optgroup><optgroup label="公演">';foreach($p as$x)$h.='<option value="production:'.(int)$x->ID.'"'.selected($selected,'production:'.$x->ID,false).'>'.esc_html($x->post_title).'</option>'; $h.='</optgroup><optgroup label="メンバー">';foreach($m as$x)$h.='<option value="member:'.(int)$x['id'].'"'.selected($selected,'member:'.$x['id'],false).'>'.esc_html($x['name']).'</option>';return$h.'</optgroup><optgroup label="外部リンク"><option value="url:"'.(str_starts_with($selected,'url:')?' selected':'').'>外部URL</option></optgroup>';}
    public function saveHomepage():void{if(!current_user_can('manage_options'))wp_die('権限がありません。');check_admin_referer('stageart_homepage');$out=[];foreach((array)wp_unslash($_POST['sections']??[])as$id=>$s){if(!is_array($s))continue;$columns=max(1,min(20,(int)($s['columns']??1)));$slots=[];foreach(array_slice((array)($s['slots']??[]),0,$columns)as$slot){if(!is_array($slot))continue;$type=($slot['type']??'link')==='heading'?'heading':'link';$ref=$type==='heading'?sanitize_text_field((string)($slot['heading']??'')):sanitize_text_field((string)($slot['content']??''));$indent=max(0,min(SiteStructure::MAX_INDENT_LEVEL,absint($slot['indent']??0)));if($type==='heading'){if($ref!=='')$slots[]=['type'=>'heading','ref'=>$ref,'indent'=>$indent];continue;}if(!$ref)continue;[$kind,$value]=array_pad(explode(':',$ref,2),2,'');if(!in_array($kind,['system','production','member','url'],true)||!$value)continue;$slots[]=['type'=>$kind,'ref'=>$kind==='url'?esc_url_raw($value):$value,'indent'=>$indent];}$out[]=['section_id'=>sanitize_key((string)$id),'heading'=>sanitize_text_field((string)($s['heading']??'')),'columns'=>$columns,'layout'=>($s['layout']??'horizontal')==='vertical'?'vertical':'horizontal','slots'=>$slots];}update_option(SiteStructure::HOME_OPTION,$out,false);wp_safe_redirect(admin_url('admin.php?page=stageart-homepage&saved=1'));exit;}
    public function saveMenu():void{if(!current_user_can('manage_options'))wp_die('権限がありません。');check_admin_referer('stageart_menu');$out=[];foreach((array)wp_unslash($_POST['menu']??[])as$i=>$item){if(!is_array($item))continue;$type=($item['type']??'content')==='folder'?'folder':'content';$content=(string)($item['content']??'');[$rt,$ref]=array_pad(explode(':',$content,2),2,'');if(!in_array($rt,['system','production','member','url'],true)){$rt='system';$ref='';}$ref=$rt==='url'?esc_url_raw($ref):sanitize_text_field($ref);$out[]=['id'=>sanitize_key((string)($item['id']??wp_generate_uuid4())),'parent_id'=>sanitize_key((string)($item['parent_id']??'')),'type'=>$type,'ref_type'=>$rt,'ref_id'=>$ref,'label'=>sanitize_text_field((string)($item['label']??'')),'order'=>max(1,(int)($item['order']??$i+1))];}update_option(SiteStructure::MENU_OPTION,$out,false);wp_safe_redirect(admin_url('admin.php?page=stageart-menu&saved=1'));exit;}
    public function renderHomepage():void{$sections=SiteStructure::homepageSections();[$p,$m]=$this->data();echo'<div class="wrap stageart-homepage-admin"><h1>トップページ設定</h1>';if(isset($_GET['saved']))echo'<div class="notice notice-success"><p>保存しました。</p></div>';echo'<p>トップページは複数の「セクション」で構成されます。各セクションごとに表示する項目数（1〜20件）と、横並び／縦並びの表示方向を選びます。各項目はコンテンツリンクまたは任意テキストの見出しとして設定でき、インデントも指定できます。実際の見た目はテーマ側のデザインに従います。</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="stageart_save_homepage">';wp_nonce_field('stageart_homepage');echo'<div id="sa-home-sections">';foreach($sections as$s)$this->section($s,$p,$m);echo'</div><p><button type="button" class="button" id="sa-add-home-section">＋ セクションを追加</button></p>';submit_button('すべてのセクションを保存');echo'</form><style>.stageart-homepage-admin{max-width:900px}.stageart-homepage-admin .sa-section{margin:16px 0;padding:16px 18px;border:1px solid #ccd0d4;background:#fff}.sa-section legend{padding:0 6px;font-weight:600}.sa-section-top{display:flex;gap:18px;align-items:flex-start;flex-wrap:wrap}.sa-slot{margin:12px 0;padding:10px 0;border-top:1px solid #eee}.sa-slot-label{font-weight:600;margin-bottom:7px}.sa-slot-controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.sa-slot-controls select{min-width:190px}.sa-slot-controls .sa-content{min-width:300px}.sa-slot-controls .sa-heading-input{min-width:300px}.sa-slot-controls .sa-indent{min-width:100px}.sa-section-actions{margin-top:10px}.sa-section-actions button{margin-right:6px}</style>';$this->homeJs($p,$m);echo'</div>';}
    private function section(array$s,array$p,array$m):void{$id=sanitize_key((string)$s['section_id']);$slots=array_values((array)($s['slots']??[]));echo'<fieldset class="sa-section" data-section-id="'.esc_attr($id).'" data-slot-count="'.(int)$s['columns'].'"><legend>セクション <span class="sa-section-number"></span></legend><input type="hidden" name="sections['.esc_attr($id).'][section_id]" value="'.esc_attr($id).'"/><div class="sa-section-top"><label>見出し（任意）<br><input type="text" class="regular-text" name="sections['.esc_attr($id).'][heading]" value="'.esc_attr($s['heading']).'" placeholder="例：同窓会からのメッセージ（空欄も可）"></label><label>表示数<br><select class="sa-columns" name="sections['.esc_attr($id).'][columns]">';for($n=1;$n<=20;$n++)echo'<option value="'.$n.'"'.selected((int)$s['columns'],$n,false).'>'.$n.'件</option>';echo'</select></label><label>表示方向<br><select name="sections['.esc_attr($id).'][layout]"><option value="horizontal"'.selected($s['layout'],'horizontal',false).'>横並び</option><option value="vertical"'.selected($s['layout'],'vertical',false).'>縦並び</option></select></label></div><p class="description">表示数を変更して保存すると、増えた項目は未設定、減った項目は削除されます。</p><div class="sa-slots">';for($i=0;$i<20;$i++){ $slot=$slots[$i]??['type'=>'none','ref'=>'','indent'=>0];$this->slot($id,$i,$slot,$p,$m,(int)$s['columns']); }echo'</div><p class="sa-section-actions"><button type="button" class="button" data-up>↑ 上へ</button><button type="button" class="button" data-down>↓ 下へ</button><button type="button" class="button-link-delete" data-remove-section>削除</button></p></fieldset>';}
    private function slot(string$id,int$i,array$slot,array$p,array$m,int$columns):void{$type=(string)($slot['type']??'none');$indent=max(0,min(3,absint($slot['indent']??0)));$selected=$type==='none'?'':$type.':'.($slot['ref']??'');$heading=$type==='heading'?(string)($slot['ref']??''):'';echo'<div class="sa-slot" data-slot="'.$i.'"'.($i>=$columns?' hidden':'').'><div class="sa-slot-label">'.($i+1).'件目</div><div class="sa-slot-controls"><select class="sa-type" name="sections['.esc_attr($id).'][slots]['.$i.'][type]"><option value="link"'.selected($type,'none',false).'>コンテンツリンク</option><option value="heading"'.selected($type,'heading',false).'>見出し</option></select><select class="sa-content" name="sections['.esc_attr($id).'][slots]['.$i.'][content]">'.$this->picker($p,$m,$selected).'</select><input class="sa-heading-input" name="sections['.esc_attr($id).'][slots]['.$i.'][heading]" value="'.esc_attr($heading).'" placeholder="見出し" style="display:none"><select class="sa-indent" name="sections['.esc_attr($id).'][slots]['.$i.'][indent]"><option value="0"'.selected($indent,0,false).'>インデントなし</option><option value="1"'.selected($indent,1,false).'>1段</option><option value="2"'.selected($indent,2,false).'>2段</option><option value="3"'.selected($indent,3,false).'>3段</option></select></div></div>';}
    private function homeJs(array$p,array$m):void{$opts=$this->picker($p,$m,'');echo'<script>(function(){const root=document.getElementById("sa-home-sections"),add=document.getElementById("sa-add-home-section"),picker='.wp_json_encode($opts).';if(!root)return;function wire(sec){const cols=sec.querySelector(".sa-columns");const update=function(){const n=parseInt(cols.value||1,10);sec.querySelectorAll(".sa-slot").forEach((r,i)=>r.hidden=i>=n);sec.dataset.slotCount=n};cols.addEventListener("change",update);update();sec.querySelectorAll(".sa-slot").forEach(function(row){const type=row.querySelector(".sa-type"),content=row.querySelector(".sa-content"),heading=row.querySelector(".sa-heading-input");const toggle=function(){const h=type.value==="heading";content.style.display=h?"none":"inline-block";heading.style.display=h?"inline-block":"none"};type.addEventListener("change",toggle);toggle()});}function renumber(){root.querySelectorAll(".sa-section").forEach((s,i)=>s.querySelector(".sa-section-number").textContent=i+1)}root.querySelectorAll(".sa-section").forEach(wire);renumber();root.addEventListener("click",function(e){const sec=e.target.closest(".sa-section");if(!sec)return;if(e.target.matches("[data-remove-section]")){sec.remove();renumber();return}if(e.target.matches("[data-up]")){const prev=sec.previousElementSibling;if(prev)root.insertBefore(sec,prev);renumber();return}if(e.target.matches("[data-down]")){const next=sec.nextElementSibling;if(next)root.insertBefore(next,sec);renumber();return}});add.addEventListener("click",function(){const id="new-"+Date.now(),div=document.createElement("fieldset");div.className="sa-section";div.dataset.sectionId=id;div.innerHTML="<legend>セクション <span class=\"sa-section-number\"></span></legend><input type=\"hidden\" name=\"sections["+id+"][section_id]\" value=\""+id+"\"><div class=\"sa-section-top\"><label>見出し（任意）<br><input type=\"text\" class=\"regular-text\" name=\"sections["+id+"][heading]\"></label><label>表示数<br><select class=\"sa-columns\" name=\"sections["+id+"][columns]\"><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option></select></label><label>表示方向<br><select name=\"sections["+id+"][layout]\"><option value=\"horizontal\">横並び</option><option value=\"vertical\">縦並び</option></select></label></div><p class=\"description\">表示数を変更して保存すると、増えた項目は未設定、減った項目は削除されます。</p><div class=\"sa-slots\"></div><p class=\"sa-section-actions\"><button type=\"button\" class=\"button\" data-up>↑ 上へ</button><button type=\"button\" class=\"button\" data-down>↓ 下へ</button><button type=\"button\" class=\"button-link-delete\" data-remove-section>削除</button></p>";const slots=div.querySelector(".sa-slots");for(let i=0;i<20;i++){const r=document.createElement("div");r.className="sa-slot";r.dataset.slot=i;r.hidden=i>0;r.innerHTML="<div class=\"sa-slot-label\">"+(i+1)+"件目</div><div class=\"sa-slot-controls\"><select class=\"sa-type\" name=\"sections["+id+"][slots]["+i+"][type]\"><option value=\"link\">コンテンツリンク</option><option value=\"heading\">見出し</option></select><select class=\"sa-content\" name=\"sections["+id+"][slots]["+i+"][content]\">"+picker+"</select><input class=\"sa-heading-input\" name=\"sections["+id+"][slots]["+i+"][heading]\" placeholder=\"見出し\" style=\"display:none\"><select class=\"sa-indent\" name=\"sections["+id+"][slots]["+i+"][indent]\"><option value=\"0\">インデントなし</option><option value=\"1\">1段</option><option value=\"2\">2段</option><option value=\"3\">3段</option></select></div>";slots.appendChild(r)}root.appendChild(div);wire(div);renumber()})})();</script>';}
    public function renderMenu():void{$menu=SiteStructure::menuItems();[$p,$m]=$this->data();echo'<div class="wrap"><h1>メニュー構成</h1>';if(isset($_GET['saved']))echo'<div class="notice notice-success"><p>保存しました。</p></div>';echo'<p>トップページのページ配置とは独立したサイトメニューです。項目種別はコンテンツリンク／フォルダです。</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('stageart_menu');echo'<input type="hidden" name="action" value="stageart_save_menu"><div id="sa-menu-items">';foreach($menu as$i=>$item)$this->menuRow($i,$item,$menu,$p,$m);echo'</div><p><button type="button" class="button" id="sa-add-menu">＋ メニュー項目を追加</button></p>';submit_button('メニューを保存');echo'</form><script>'. $this->menuJs($p,$m).'</script></div>';}
    private function menuRow(int$i,array$item,array$all,array$p,array$m):void{$sel=$item['ref_type'].':'.$item['ref_id'];echo'<div class="card sa-menu-row" style="margin:10px 0;padding:12px"><input type="hidden" name="menu['.$i.'][id]" value="'.esc_attr($item['id']).'"><p><label>表示名 <input name="menu['.$i.'][label]" value="'.esc_attr($item['label']).'" required></label>　<label>順序 <input type="number" min="1" name="menu['.$i.'][order]" value="'.esc_attr($item['order']).'" style="width:70px"></label>　<label>項目種別 <select name="menu['.$i.'][type]"><option value="content"'.selected($item['type'],'content',false).'>コンテンツリンク</option><option value="folder"'.selected($item['type'],'folder',false).'>フォルダ</option></select></label>　<label>親 <select name="menu['.$i.'][parent_id]"><option value="">（なし）</option>';foreach($all as$x){if($x['id']===$item['id'])continue;echo'<option value="'.esc_attr($x['id']).'"'.selected($item['parent_id'],$x['id'],false).'>'.esc_html($x['label']?:'（無題）').'</option>';}echo'</select></label></p><p><label>コンテンツリンク <select name="menu['.$i.'][content]">'.$this->picker($p,$m,$sel).'</select></label> <button type="button" class="button-link-delete" data-remove-menu>削除</button></p></div>';}
    private function menuJs(array$p,array$m):string{$opts=$this->picker($p,$m,'');return'<script>(function(){const root=document.getElementById("sa-menu-items"),add=document.getElementById("sa-add-menu"),opts='.wp_json_encode($opts).';if(!root||!add)return;add.onclick=function(){const i=root.children.length,row=document.createElement("div");row.className="card sa-menu-row";row.style="margin:10px 0;padding:12px";row.innerHTML="<input type=\"hidden\" name=\"menu["+i+"][id]\" value=\"new-"+Date.now()+"\"><p><label>表示名 <input name=\"menu["+i+"][label]\" required></label>　<label>順序 <input type=\"number\" min=\"1\" name=\"menu["+i+"][order]\" value=\""+(i+1)+"\"></label>　<label>項目種別 <select name=\"menu["+i+"][type]\"><option value=\"content\">コンテンツリンク</option><option value=\"folder\">フォルダ</option></select></label>　<label>親 <select name=\"menu["+i+"][parent_id]\"><option value=\"\">（なし）</option></select></label></p><p><label>コンテンツリンク <select name=\"menu["+i+"][content]\">"+opts+"</select></label> <button type=\"button\" class=\"button-link-delete\" data-remove-menu>削除</button></p>";root.appendChild(row)};root.onclick=function(e){if(e.target.matches("[data-remove-menu]"))e.target.closest(".sa-menu-row").remove()}})();</script>'}
}
